#include "../v7/model.h"
#include <random>
using namespace v2;
struct Example{Board b;double target;int source,d,weight,split;};
int main(int argc,char**argv){try{if(argc!=7)throw std::runtime_error("MODEL DATA ANCHORS SEED EPOCHS OUT");init();Learner m,base;m.load(argv[1]);base.load("training/v7/base.ntd");std::ifstream f(argv[2]);std::vector<Example> all;Example e;while(f>>e.source>>e.d>>e.weight>>e.split>>e.target){for(auto&r:e.b){int n;f>>n;r=n;}if(!f)throw std::runtime_error("data");all.push_back(e);}std::ifstream anchors(argv[3]);std::vector<Board> boards;int label;while(anchors>>label){Board b;for(auto&r:b){int n;anchors>>n;r=n;}if(!anchors)throw std::runtime_error("anchors");boards.push_back(b);}std::vector<int> order;for(int i=0;i<int(all.size());i++)if(!all[i].split)for(int w=0;w<all[i].weight;w++)order.push_back(i);std::mt19937 rng(std::stoul(argv[4]));int epochs=std::stoi(argv[5]);std::ofstream out(argv[6]);out<<std::setprecision(17);
 auto emit=[&](int epoch){double sq[2]{},bias[2]{};int n[2]{};out<<"{\"epoch\":"<<epoch<<",\"predictions\":[";for(size_t i=0;i<all.size();i++){const auto&e=all[i];double v=m.value(e.b,0),err=v-e.target;sq[e.split]+=err*err;bias[e.split]+=err;n[e.split]++;out<<(i?",":"")<<v;}double drift=0;for(auto&b:boards){double d=m.value(b,0)-base.value(b,0);drift+=d*d;}out<<"],\"rmse\":["<<std::sqrt(sq[0]/n[0])<<','<<std::sqrt(sq[1]/n[1])<<"],\"bias\":["<<bias[0]/n[0]<<','<<bias[1]/n[1]<<"],\"normalDriftRMSE\":"<<std::sqrt(drift/boards.size())<<"}"<<std::endl;};
 emit(0);for(int epoch=1;epoch<=epochs;epoch++){std::shuffle(order.begin(),order.end(),rng);for(int i:order)m.update(all[i].b,all[i].target,.01);if(epoch==1||epoch==10||epoch==100)emit(epoch);}for(int s=1;s<3;s++)if(m.base.w[s]!=base.base.w[s])throw std::runtime_error("late-stage changed");
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
